const inputItem = $input.all()[0];

// 1. Acceder al dato binario 'data'
const rawBinaryData = inputItem.binary ? inputItem.binary.data : null; 

if (!rawBinaryData) {
    // Si no hay dato binario, salir.
    return [];
}

// 2. Comprobar si es un array. Si no lo es, envolverlo en un array.
let allBinaryFiles;
if (Array.isArray(rawBinaryData)) {
    allBinaryFiles = rawBinaryData;
} else {
    // Es un solo archivo binario (un objeto), lo convertimos en un array de un elemento.
    allBinaryFiles = [rawBinaryData]; 
}

if (allBinaryFiles.length === 0) {
    return [];
}

let output = [];

// 3. Itera sobre el array de archivos binarios (que ahora está garantizado que es un array)
for (const file of allBinaryFiles) {
    let type;

    // Identifica el tipo de archivo por su MimeType
    if (file.mimeType === 'image/jpeg' || file.mimeType === 'image/png') {
        type = 'image';
    } else if (file.mimeType === 'video/mp4') {
        type = 'video';
    } else {
        // Ignorar otros tipos de archivo
        continue; 
    }

    // Crea un nuevo elemento de salida para este archivo
    output.push({
        // Incluye metadatos en el JSON
        json: {
            processType: type,
            fileName: file.fileName || 'file',
            mimeType: file.mimeType
        },
        // Adjunta el archivo binario usando la clave 'data'
        binary: {
            data: file 
        }
    });
}

return output;

const items = $input.all();

for (const item of items) {
  // Verifica si la propiedad 'Imágenes o videos adjuntos' existe
  if (item.json['Imágenes o videos adjuntos']) {
    const url = item.json['Imágenes o videos adjuntos'];
    console.log('URL encontrada:', url); // Imprime la URL para depurar

    // Asegúrate de que sea una cadena de texto válida
    if (typeof url === 'string' && url.trim() !== '') {
      // Expresión regular para extraer el ID de la URL de Drive
      const regex = /(?:\/open\?id=|\/d\/)([^/]+)/;
      const match = url.match(regex);

      if (match && match[1]) {
        // Crea una nueva variable llamada 'driveFileId' con solo el ID limpio
        item.json.driveFileId = match[1];
        console.log('ID extraído:', match[1]);
      } else {
        console.log('No se pudo extraer el ID de la URL:', url); 
      }
    } else {
      console.log('URL no válida en el campo "Imágenes o videos adjuntos":', url); 
    }
  } else {
    console.log('No existe el campo "Imágenes o videos adjuntos" en este item:', item.json); 
  }
}

return items;

